sql.where:
AND name ILIKE '%' || #{keyword} || '%'
AND type = #{type}
AND task_type = #{taskType}
AND project_id = #{projectId}
AND status = #{status}
AND status <> 'deleted'

mapper.update:
UPDATE dataset
name = #{name}, type = #{type}, format = #{format}, task_type = #{taskType}, storage_pool_id = #{storagePoolId}, sample_count = #{sampleCount}, tags = #{tags}::jsonb, description = #{description}, license = #{license}, status = #{status}, project_id = #{projectId}, updated_at = NOW()
WHERE id = #{id}
